-- Team membership is the single control for support module access.
create or replace function public.support_set_team_member(p_team_id uuid,p_email text,p_team_role text,p_is_active boolean default true) returns uuid language plpgsql security definer set search_path='' as $$declare v_user uuid;v_has_membership boolean;begin if not public.has_admin_permission('support','edit') then raise exception 'Support edit permission required';end if;if not public.is_admin() and not exists(select 1 from public.support_team_members where team_id=p_team_id and user_id=auth.uid() and is_active and team_role='supervisor') then raise exception 'Support supervisor access required';end if;if p_team_role not in('agent','supervisor') then raise exception 'Invalid team role';end if;select id into v_user from public.profiles where lower(email)=lower(trim(p_email)) and role::text in('admin','staff') and staff_status='active' limit 1;if v_user is null then raise exception 'Active admin/staff account not found for this email';end if;insert into public.support_team_members(team_id,user_id,team_role,is_active) values(p_team_id,v_user,p_team_role,p_is_active) on conflict(team_id,user_id) do update set team_role=excluded.team_role,is_active=excluded.is_active;select exists(select 1 from public.support_team_members where user_id=v_user and is_active) into v_has_membership;insert into public.admin_user_permissions(user_id,module_key,action_key,allowed,updated_by,updated_at,reason) values(v_user,'support','view',v_has_membership,auth.uid(),now(),'Managed through Secure Support team access'),(v_user,'support','edit',v_has_membership,auth.uid(),now(),'Managed through Secure Support team access') on conflict(user_id,module_key,action_key) do update set allowed=excluded.allowed,updated_by=excluded.updated_by,updated_at=excluded.updated_at,reason=excluded.reason,expires_at=null;return v_user;end$$;
revoke all on function public.support_set_team_member(uuid,text,text,boolean) from public,anon;
grant execute on function public.support_set_team_member(uuid,text,text,boolean) to authenticated;
